public class EspressoDialing {
    public static String evaluarExtraccion(double dosisIn, double yieldOut, int segundos) {
        double brewRatio = yieldOut / dosisIn;
        if (segundos < 22) {
            return "Sub-extraccion: Acido y rapido. Ajustar molienda a micrones menores.";
        } else if (segundos > 32) {
            return "Sobre-extraccion: Amargo y astringente. Abrir molienda.";
        }
        return String.format("Extraccion equilibrada: Ratio 1:%.1f en %d segundos.", brewRatio, segundos);
    }
}
